<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Falling Sand Sandbox</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #10131a;
    --panel: #1a202b;
    --panel2: #242d3a;
    --text: #eef4ff;
    --muted: #9eabbc;
    --accent: #ffd45a;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    background:
      radial-gradient(circle at 50% -20%, #26354b 0%, #111722 42%, #0c1016 100%);
    color: var(--text);
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    display: grid;
    place-items: center;
    padding: 22px;
  }

  .app {
    width: min(760px, 100%);
    display: grid;
    gap: 16px;
    justify-items: center;
  }

  header {
    text-align: center;
  }

  h1 {
    font-size: clamp(1.45rem, 3vw, 2rem);
    letter-spacing: .08em;
    text-transform: uppercase;
    margin: 0 0 5px;
  }

  header p {
    margin: 0;
    color: var(--muted);
    font-size: .92rem;
  }

  .controls {
    width: min(660px, 100%);
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 9px;
    padding: 12px;
    background: rgba(25, 32, 43, .88);
    border: 1px solid #344154;
    border-radius: 15px;
    box-shadow: 0 12px 35px rgba(0, 0, 0, .28);
  }

  button {
    border: 1px solid #46546a;
    border-radius: 10px;
    background: linear-gradient(180deg, #303b4d, #222b38);
    color: var(--text);
    padding: 9px 13px;
    font: inherit;
    font-size: .88rem;
    font-weight: 700;
    cursor: pointer;
    transition: transform .12s ease, border-color .12s ease, filter .12s ease;
    user-select: none;
  }

  button:hover {
    transform: translateY(-1px);
    filter: brightness(1.12);
  }

  button:active { transform: translateY(1px); }

  button.selected {
    border-color: var(--accent);
    box-shadow: 0 0 0 2px rgba(255, 212, 90, .2), inset 0 0 15px rgba(255, 212, 90, .12);
    color: #fff6c9;
  }

  #clear {
    border-color: #a85555;
    background: linear-gradient(180deg, #63353b, #43252b);
  }

  .canvas-frame {
    padding: 10px;
    background: #080b10;
    border: 1px solid #3b495d;
    border-radius: 14px;
    box-shadow:
      0 22px 50px rgba(0, 0, 0, .42),
      inset 0 0 25px rgba(0, 0, 0, .7);
  }

  canvas {
    display: block;
    width: 600px;
    height: 600px;
    max-width: none;
    background: #111923;
    cursor: crosshair;
    image-rendering: pixelated;
    touch-action: none;
  }

  .hint {
    margin: 0;
    color: var(--muted);
    font-size: .83rem;
    text-align: center;
  }
</style>
</head>
<body>
<main class="app">
  <header>
    <h1>Falling Sand</h1>
    <p>Choose a material, then click and drag across the chamber.</p>
  </header>

  <section class="controls" aria-label="Material controls">
    <button id="mat-sand" class="selected" type="button">Sand</button>
    <button id="mat-water" type="button">Water</button>
    <button id="mat-wall" type="button">Wall</button>
    <button id="mat-acid" type="button">Acid</button>
    <button id="mat-empty" type="button">Eraser</button>
    <button id="clear" type="button">Clear Grid</button>
  </section>

  <div class="canvas-frame">
    <canvas id="sand" width="600" height="600" aria-label="Falling sand simulation canvas"></canvas>
  </div>

  <p class="hint">Sand sinks through liquids. Water spreads. Acid erodes sand and walls.</p>
</main>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("sand");
  const ctx = canvas.getContext("2d", { alpha: false });

  const w = 100;
  const h = 100;
  const cellSize = canvas.width / w;

  const EMPTY = 0;
  const SAND = 1;
  const WATER = 2;
  const WALL = 3;
  const ACID = 4;

  const names = ["empty", "sand", "water", "wall", "acid"];
  const codes = {
    empty: EMPTY,
    sand: SAND,
    water: WATER,
    wall: WALL,
    acid: ACID
  };

  const colors = {
    sand: "#e4b74d",
    water: "#3d9fe8",
    wall: "#718092",
    acid: "#85df4b"
  };

  const grid = new Uint8Array(w * h);
  const moved = new Uint8Array(w * h);
  let randomSeed = 0x6d2b79f5;
  let selected = "sand";

  function index(x, y) {
    return y * w + x;
  }

  function inBounds(x, y) {
    return x >= 0 && x < w && y >= 0 && y < h;
  }

  function random() {
    randomSeed = (randomSeed * 1664525 + 1013904223) >>> 0;
    return randomSeed / 4294967296;
  }

  function direction() {
    return random() < 0.5 ? -1 : 1;
  }

  function moveParticle(x, y, nx, ny, material) {
    const from = index(x, y);
    const to = index(nx, ny);
    grid[from] = EMPTY;
    grid[to] = material;
    moved[to] = 1;
  }

  function sandStep(x, y) {
    const here = index(x, y);
    const belowY = y + 1;

    if (belowY < h) {
      const below = index(x, belowY);
      const belowMaterial = grid[below];

      if (belowMaterial === EMPTY) {
        moveParticle(x, y, x, belowY, SAND);
        return;
      }

      if (belowMaterial === WATER || belowMaterial === ACID) {
        /*
          Let liquid escape sideways before sand enters its cell whenever
          possible. This keeps liquid local rather than pushing it upward
          through a tall stream of falling sand.
        */
        const first = direction();
        const options = [first, -first];

        for (const dx of options) {
          const sideX = x + dx;
          if (sideX >= 0 && sideX < w) {
            const side = index(sideX, belowY);
            if (grid[side] === EMPTY) {
              grid[side] = belowMaterial;
              moved[side] = 1;
              grid[below] = SAND;
              grid[here] = EMPTY;
              moved[below] = 1;
              return;
            }
          }
        }

        /*
          In a fully enclosed liquid pocket, use a direct exchange. Both
          particles are marked as moved, so neither can move again this step.
        */
        grid[here] = belowMaterial;
        grid[below] = SAND;
        moved[here] = 1;
        moved[below] = 1;
        return;
      }

      const first = direction();
      for (const dx of [first, -first]) {
        const nx = x + dx;
        if (nx >= 0 && nx < w && grid[index(nx, belowY)] === EMPTY) {
          moveParticle(x, y, nx, belowY, SAND);
          return;
        }
      }
    }
  }

  function fluidStep(x, y, material) {
    const belowY = y + 1;

    if (belowY < h && grid[index(x, belowY)] === EMPTY) {
      moveParticle(x, y, x, belowY, material);
      return;
    }

    if (belowY < h) {
      const firstDiagonal = direction();
      for (const dx of [firstDiagonal, -firstDiagonal]) {
        const nx = x + dx;
        if (nx >= 0 && nx < w && grid[index(nx, belowY)] === EMPTY) {
          moveParticle(x, y, nx, belowY, material);
          return;
        }
      }
    }

    const firstSide = direction();
    for (const dx of [firstSide, -firstSide]) {
      const nx = x + dx;
      if (nx >= 0 && nx < w && grid[index(nx, y)] === EMPTY) {
        moveParticle(x, y, nx, y, material);
        return;
      }
    }
  }

  function acidStep(x, y) {
    const targets = [];
    const checks = [
      [x, y + 1],
      [x - 1, y],
      [x + 1, y]
    ];

    for (const [tx, ty] of checks) {
      if (!inBounds(tx, ty)) continue;
      const material = grid[index(tx, ty)];
      if (material === SAND || material === WALL) {
        targets.push([tx, ty]);
      }
    }

    if (targets.length) {
      const target = targets[Math.floor(random() * targets.length)];
      grid[index(target[0], target[1])] = EMPTY;
    }

    fluidStep(x, y, ACID);
  }

  function step() {
    moved.fill(0);

    /*
      Bottom-to-top order is essential: after a particle moves downward,
      its destination row has already been processed and cannot move again
      during this simulation step.
    */
    for (let y = h - 1; y >= 0; y--) {
      for (let x = 0; x < w; x++) {
        const i = index(x, y);
        if (moved[i]) continue;

        const material = grid[i];
        if (material === SAND) sandStep(x, y);
        else if (material === WATER) fluidStep(x, y, WATER);
        else if (material === ACID) acidStep(x, y);
      }
    }
  }

  function render() {
    ctx.fillStyle = "#111923";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const material = grid[index(x, y)];
        if (material === EMPTY) continue;

        const name = names[material];
        ctx.fillStyle = colors[name];
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);

        if (material === WALL) {
          ctx.fillStyle = "rgba(255,255,255,.10)";
          ctx.fillRect(x * cellSize, y * cellSize, cellSize, 1);
        } else if (material === WATER || material === ACID) {
          ctx.fillStyle = "rgba(255,255,255,.12)";
          ctx.fillRect(x * cellSize, y * cellSize, 1, cellSize);
        }
      }
    }
  }

  function clearGrid() {
    grid.fill(EMPTY);
    render();
  }

  function getCell(x, y) {
    x = Math.floor(x);
    y = Math.floor(y);
    if (!inBounds(x, y)) return "empty";
    return names[grid[index(x, y)]];
  }

  function setCell(x, y, material) {
    x = Math.floor(x);
    y = Math.floor(y);
    if (!inBounds(x, y) || !(material in codes)) return;
    grid[index(x, y)] = codes[material];
    render();
  }

  function tick(n) {
    n = Math.max(0, Math.floor(Number(n) || 0));
    for (let i = 0; i < n; i++) step();
    render();
  }

  window.sim = {
    w,
    h,
    tick,
    get: getCell,
    set: setCell,
    clear: clearGrid
  };

  const materialButtons = {
    sand: document.getElementById("mat-sand"),
    water: document.getElementById("mat-water"),
    wall: document.getElementById("mat-wall"),
    acid: document.getElementById("mat-acid"),
    empty: document.getElementById("mat-empty")
  };

  function chooseMaterial(material) {
    selected = material;
    for (const [name, button] of Object.entries(materialButtons)) {
      button.classList.toggle("selected", name === material);
    }
  }

  for (const [material, button] of Object.entries(materialButtons)) {
    button.addEventListener("click", () => chooseMaterial(material));
  }

  document.getElementById("clear").addEventListener("click", clearGrid);

  function eventCell(event) {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((event.clientX - rect.left) * w / rect.width);
    const y = Math.floor((event.clientY - rect.top) * h / rect.height);
    return { x, y };
  }

  function paintDot(cx, cy) {
    const material = codes[selected];
    const radius = selected === "wall" ? 1 : 1;

    for (let oy = -radius; oy <= radius; oy++) {
      for (let ox = -radius; ox <= radius; ox++) {
        if (ox * ox + oy * oy > radius * radius + 0.3) continue;
        const x = cx + ox;
        const y = cy + oy;
        if (inBounds(x, y)) grid[index(x, y)] = material;
      }
    }
  }

  function paintLine(a, b) {
    let x0 = a.x;
    let y0 = a.y;
    const x1 = b.x;
    const y1 = b.y;
    const dx = Math.abs(x1 - x0);
    const sx = x0 < x1 ? 1 : -1;
    const dy = -Math.abs(y1 - y0);
    const sy = y0 < y1 ? 1 : -1;
    let error = dx + dy;

    while (true) {
      paintDot(x0, y0);
      if (x0 === x1 && y0 === y1) break;
      const e2 = error * 2;
      if (e2 >= dy) {
        error += dy;
        x0 += sx;
      }
      if (e2 <= dx) {
        error += dx;
        y0 += sy;
      }
    }
  }

  let drawing = false;
  let lastPoint = null;

  canvas.addEventListener("pointerdown", (event) => {
    drawing = true;
    lastPoint = eventCell(event);
    canvas.setPointerCapture(event.pointerId);
    paintDot(lastPoint.x, lastPoint.y);
    render();
  });

  canvas.addEventListener("pointermove", (event) => {
    if (!drawing) return;
    const nextPoint = eventCell(event);
    paintLine(lastPoint, nextPoint);
    lastPoint = nextPoint;
    render();
  });

  function stopDrawing(event) {
    drawing = false;
    lastPoint = null;
    if (canvas.hasPointerCapture(event.pointerId)) {
      canvas.releasePointerCapture(event.pointerId);
    }
  }

  canvas.addEventListener("pointerup", stopDrawing);
  canvas.addEventListener("pointercancel", stopDrawing);

  let previousTime = performance.now();
  let accumulator = 0;

  function animate(now) {
    accumulator += now - previousTime;
    previousTime = now;

    while (accumulator >= 45) {
      step();
      accumulator -= 45;
    }

    render();
    requestAnimationFrame(animate);
  }

  render();
  requestAnimationFrame(animate);
})();
</script>
</body>
</html>
